.view_S1N13_top span{color:#2980b9;} @media screen and (max-width: 39.9375em) { } 안산시 전·현직 시·도의원 13인, 김철진 안산시장 경선후보 지지 선언 [사진=김철진 예비후보] 안산 갑(甲), 을(乙), 병(丙) 모든 지역구의 경계를 완전히 허물고 총망라한 더불어민주당 전·현직 시·도의원 들이 김철진 안산시장 경선후보를 향한 전폭적인 지지선언을 발표하며 총결집을 공식화했다. 이는 특정 지역에 국한된 지지가 아닌, 안산 전역의 민주당 핵심 세력이 오직 김철진만을 유일한 대안으로 인정했다는 강력한 증거다. 안산시 갑·을·병, 전·현직 시·도의원 13인, 김철진 안산시장 경선후보 전폭 지지 선언 [사진=김철진 예비후보] 다가오는 6·3 지방선거 안산시장 경선판의 승부를 결정짓는 확정적 지지선언이자, 김철진 경선후보가 당원과 시민의 절대적 지지를 받는 ‘이견 없는 필승 카드’임에 확실한 쐐기를 박는 선포다. 김철진 경선후보 측은 11일 오후, 전·현직 시·도의원 13인의 합동 지지선언에 대해 “안산의 절박한 위기 앞에 갑·을·병이라는 지역적 경계마저 완벽히 뛰어넘어, 민주당의 진짜 주역들이 ‘김철진’이라는 이름 아래 하나의 거대한 강물로 뭉쳤다”며, “전 지역구를 아우르는 이번 역사적 대통합은 단순한 연대를 넘어, 무능한 시정을 심판하고 안산 대전환을 이뤄낼 폭발적인 동력이 될 것”이라고 강한 자신감을 천명했다. 김철진 경선후보 측은 안산 정치의 핵심인 13인의 의원단이 김철진 후보를 선택한 결정적 이유로 ‘안산대전환의 비전, 한 점 흠결 없는 도덕성, 불의와 타협하지 않는 칼날 같은 선명성’을 꼽았다. 김철진 경선후보는 “12·3 불법 계엄의 순간에서도 내란세력과 맞서며 윤석열 파면과 이재명 정부 출범의 최선봉에 섰던 ‘진짜 민주당원’이자 실천하는 현장 전문가”라며, “모두를 아우르는 넒은 포용력을 바탕으로 범죄 전력이나 기회주의적 철새 정치와는 완벽히 단절된 인물로 깨끗한 도덕성만이 탈당과 막무가내식 권력을 휘두르는 구태정치와는 완벽히 단절할수 있고, 무능한 현 시정을 심판할 수 있는 유일한 후보임을 안산 갑·을·병 의원단이 깊이 공감한 것”이라고 강조했다. 김철진 경선후보는 안산 갑·을·병을 아우르는 전폭적 지지선언에 대해 “오늘은 지역구를 초월하여 하나 된 민주당이 출발하는 위대한 첫날이며, 그동안 출신과 지연 등으로 분열되었던 낡은 과거를 끊어내고 진정한 대통합의 포용으로 구태 정치를 완벽히 청산하는 날”이라고 선언했다. 이어 “이번 압도적 지지는 저 김철진이 민주당의 정체성, 칼날 같은 선명성, 그리고 한 점 부끄럼 없는 도덕성을 완벽하게 갖춘 진짜 인물임을 철저히 검증받은 결과”라며, “저에게 안산 전체의 운명을 걸겠다는 이 엄중하고도 거대한 명령을 받들어, 기득권의 저항을 맨 앞에서 무참히 부수고 다가오는 6·3 지방선거에서 경쟁자들을 압도하며 반드시 승리의 깃발을 꽂겠다”고 결연한 의지를 밝혔다. 안산 갑·을·병을 총망라한 지지 세력을 등에 업은 김철진 경선후보는 이제 단순한 대세론을 넘어 경선 승리에 완벽한 쐐기를 박으며, 안산시장 선거판을 완벽히 장악해 나갈 계획이다. [지지 선언 동참 더불어민주당 안산시 전·현직 시·도의원 일동 (총 13명)] 강태형, 이은미, 유재수, 박은경, 박은정, 선현우, 최진호, 황은화, 김동수, 나정숙, 주미희, 박영근, 추연호 $(function() { const copyUrlOptions=document.querySelectorAll(".urlBtns, .sns_clipboard"); // 주소복사 이벤트 (v11-fl-v2 수정) copyUrlOptions.forEach(selector=>{ selector.addEventListener("click", (e)=>{ const target=e.target, targetBtn=target.closest("[data-clipboard-text]"); if (targetBtn===null) return; const url=targetBtn.getAttribu