투표와 여론조사를 거쳐 최종 후보를 가렸다. 최종 결과는 교체보다 연속성에 무게를 둔 당의 선택으로 해석된다. 현직 시장이라는 인지도와 시정 경험, 그리고 임기 중 추진해 온 각종 현안을 이어갈 수 있다는 점이 경선 과정에서 강점으로 작용한 것이라는 지역 정가의 목소리다. 이로써 국민의힘은 고양시장 본선 주자로 이동환 시장을 내세워 선거전에 돌입하게 됐다. 이동환 시장은 경제자유구역, 광역교통망 확충, 대형 공연·관광 연계 전략 등 민선 8기 핵심 사업의 지속 추진을 명분으로 내세울 가능성이 커졌다. 경선 승리로 당내 정통성과 조직 결집의 발판을 마련했다는 점도 향후 본선 전략에서 적지 않은 힘이 될 예정이다. 다만 본선이 순탄하지만은 않을 것이라는 관측도 나온다. 최근 고양 지역 선거 구도는 더불어민주당 강세 흐름 속에서 전개돼 왔고, 국민의힘 입장에서는 현직 시장의 성과를 얼마나 시민이 와닿을 수 있게 만드느냐가 남은 승부의 핵심 변수가 될 것으로 전망된다. 기사이력코드 취재(기획) 취재(기획) 취재(제보) 취재(자료보완) 보도자료 SNS 서핑 기타(국내외 논문·학술지) 기타(증권사 리포트) 기타(타 언론사 후속보도) 메트로신문 안성기 기자 ask9990@metroseoul.co.kr 다른기사 보기 Copyright ⓒ 메트로신문 & metroseoul.co.kr function goSearchPage(searchText){ location.href="/search?searchText="+encodeURI(searchText); return; } (function () { $.ajax({ type : "GET", url : "/wps/engine/rest/35?type=COMPONENT", success: function (data) { $("#ZxBejhqxJS").after(data); $("#ZxBejhqxJS").remove(); } }); })() 메트로신문 지면 PDF 보기 // 현재 날짜 구하기 var now = new Date(); // 요일 체크 (0 = 일요일, 1 = 월요일, ..., 6 = 토요일) var dayName = now.getDay(); // 주말이면 금요일 날짜로 바꾸기 if (dayName === 0) { // 일요일이면 now.setDate(now.getDate() - 2); // 금요일로 이동 } else if (dayName === 6) { // 토요일이면 now.setDate(now.getDate() - 1); // 금요일로 이동 } // MMddDate: MMDD 형식 var MMddDate = ("0" + (now.getMonth() + 1)).slice(-2) + ("0" + now.getDate()).slice(-2); // yyyyMMddDate: yyyy/MM/dd 형식 var yyyyMMddDate = now.getFullYear() + "/" + ("0" + (now.getMonth() + 1)).slice(-2) + "/" + ("0" + now.getDate()).slice(-2); // yyyyMMddDate2: yyyy-MM-dd 형식 var yyyyMMddDate2 = now.getFullYear() + "-" + ("0" + (now.getMonth() + 1)).slice(-2) + "-" + ("0" + now.getDate()).slice(-2); // 이미지 src URL 생성 var imageUrl = "https://pdf.metroseoul.co.kr/pdf/" + yyyyMMddDate + "/img/s10/kr_metro_1_" + MMddDate + "_01.jpg"; // HTML 요소에 값 삽입 document.getElementById('pdfImage').setAttribute('src', imageUrl); document.getElementById('pdfDate').textContent = yyyyMMddDate2; (function () { $.ajax({ type : "GET", url : "/wps/engin